-- APPA v3 bootstrap, for a project without an APPA schema. Source tables are untouched.
BEGIN;
CREATE SCHEMA IF NOT EXISTS appa;
SET LOCAL search_path TO appa;
CREATE TABLE IF NOT EXISTS model_versions ( id VARCHAR NOT NULL, target VARCHAR NOT NULL, name VARCHAR NOT NULL, units VARCHAR NOT NULL, manifest JSON NOT NULL, PRIMARY KEY (id) ) ;
ALTER TABLE model_versions ENABLE ROW LEVEL SECURITY;
CREATE TABLE IF NOT EXISTS photos ( id VARCHAR NOT NULL, captured_at VARCHAR, latitude FLOAT, longitude FLOAT, mission VARCHAR NOT NULL, thumbnail_url VARCHAR NOT NULL, image_url VARCHAR NOT NULL, original_url VARCHAR NOT NULL, metadata_json JSON NOT NULL, local_image VARCHAR, image_sha256 VARCHAR, PRIMARY KEY (id) ) ;
CREATE INDEX IF NOT EXISTS ix_photos_captured_at ON photos (captured_at);
CREATE INDEX IF NOT EXISTS ix_photos_latitude ON photos (latitude);
CREATE INDEX IF NOT EXISTS ix_photos_mission ON photos (mission);
ALTER TABLE photos ENABLE ROW LEVEL SECURITY;
CREATE TABLE IF NOT EXISTS prediction_runs ( id VARCHAR NOT NULL, kind VARCHAR NOT NULL, status VARCHAR NOT NULL, created_at VARCHAR NOT NULL, completed_at VARCHAR, provenance JSON NOT NULL, PRIMARY KEY (id) ) ;
CREATE INDEX IF NOT EXISTS ix_prediction_runs_status ON prediction_runs (status);
ALTER TABLE prediction_runs ENABLE ROW LEVEL SECURITY;
CREATE TABLE IF NOT EXISTS annotation_revisions ( id VARCHAR NOT NULL, photo_id VARCHAR NOT NULL, revision INTEGER NOT NULL, image_sha256 VARCHAR NOT NULL, reviewer VARCHAR NOT NULL, created_at VARCHAR NOT NULL, regions JSON NOT NULL, PRIMARY KEY (id), UNIQUE (photo_id, revision), FOREIGN KEY(photo_id) REFERENCES photos (id) ) ;
CREATE INDEX IF NOT EXISTS ix_annotation_revisions_photo_id ON annotation_revisions (photo_id);
ALTER TABLE annotation_revisions ENABLE ROW LEVEL SECURITY;
CREATE TABLE IF NOT EXISTS calibrations ( id VARCHAR NOT NULL, model_id VARCHAR NOT NULL, created_at VARCHAR NOT NULL, coverage FLOAT NOT NULL, log_radius FLOAT NOT NULL, manifest JSON NOT NULL, PRIMARY KEY (id), FOREIGN KEY(model_id) REFERENCES model_versions (id) ) ;
CREATE INDEX IF NOT EXISTS ix_calibrations_model_id ON calibrations (model_id);
ALTER TABLE calibrations ENABLE ROW LEVEL SECURITY;
CREATE TABLE IF NOT EXISTS catalog_snapshots ( id VARCHAR NOT NULL, photo_id VARCHAR NOT NULL, source VARCHAR NOT NULL, imported_at VARCHAR NOT NULL, data JSON NOT NULL, PRIMARY KEY (id), FOREIGN KEY(photo_id) REFERENCES photos (id) ) ;
CREATE INDEX IF NOT EXISTS ix_catalog_snapshots_photo_id ON catalog_snapshots (photo_id);
ALTER TABLE catalog_snapshots ENABLE ROW LEVEL SECURITY;
CREATE TABLE IF NOT EXISTS input_assets ( id VARCHAR NOT NULL, photo_id VARCHAR NOT NULL, image_sha256 VARCHAR NOT NULL, local_path VARCHAR, kind VARCHAR NOT NULL, provenance JSON NOT NULL, PRIMARY KEY (id), FOREIGN KEY(photo_id) REFERENCES photos (id) ) ;
CREATE INDEX IF NOT EXISTS ix_input_assets_image_sha256 ON input_assets (image_sha256);
CREATE INDEX IF NOT EXISTS ix_input_assets_photo_id ON input_assets (photo_id);
ALTER TABLE input_assets ENABLE ROW LEVEL SECURITY;
CREATE TABLE IF NOT EXISTS jobs ( id VARCHAR NOT NULL, idempotency_key VARCHAR NOT NULL, photo_id VARCHAR NOT NULL, run_id VARCHAR NOT NULL, model_ids JSON NOT NULL, status VARCHAR NOT NULL, attempts INTEGER NOT NULL, created_at VARCHAR NOT NULL, updated_at VARCHAR NOT NULL, lease_until FLOAT, lease_token VARCHAR, error VARCHAR, PRIMARY KEY (id), UNIQUE (idempotency_key), FOREIGN KEY(photo_id) REFERENCES photos (id), FOREIGN KEY(run_id) REFERENCES prediction_runs (id) ) ;
CREATE INDEX IF NOT EXISTS ix_jobs_status ON jobs (status);
ALTER TABLE jobs ENABLE ROW LEVEL SECURITY;
CREATE TABLE IF NOT EXISTS overlays ( id VARCHAR NOT NULL, photo_id VARCHAR NOT NULL, target VARCHAR NOT NULL, image_sha256 VARCHAR NOT NULL, model_version VARCHAR NOT NULL, created_at VARCHAR NOT NULL, manifest JSON NOT NULL, payload JSON NOT NULL, PRIMARY KEY (id), FOREIGN KEY(photo_id) REFERENCES photos (id) ) ;
CREATE INDEX IF NOT EXISTS ix_overlays_photo_id ON overlays (photo_id);
ALTER TABLE overlays ENABLE ROW LEVEL SECURITY;
CREATE TABLE IF NOT EXISTS satellite_matchups ( id VARCHAR NOT NULL, photo_id VARCHAR NOT NULL, dataset_sha256 VARCHAR NOT NULL, data JSON NOT NULL, PRIMARY KEY (id), FOREIGN KEY(photo_id) REFERENCES photos (id) ) ;
CREATE INDEX IF NOT EXISTS ix_satellite_matchups_photo_id ON satellite_matchups (photo_id);
ALTER TABLE satellite_matchups ENABLE ROW LEVEL SECURITY;
CREATE TABLE IF NOT EXISTS estimates ( id VARCHAR NOT NULL, photo_id VARCHAR NOT NULL, run_id VARCHAR NOT NULL, model_id VARCHAR NOT NULL, matchup_id VARCHAR, target VARCHAR NOT NULL, value FLOAT NOT NULL, role VARCHAR NOT NULL, split VARCHAR, scene_group VARCHAR, created_at VARCHAR NOT NULL, evidence JSON NOT NULL, PRIMARY KEY (id), UNIQUE (run_id, photo_id, model_id), CONSTRAINT positive_estimate CHECK (value > 0), FOREIGN KEY(photo_id) REFERENCES photos (id), FOREIGN KEY(run_id) REFERENCES prediction_runs (id), FOREIGN KEY(model_id) REFERENCES model_versions (id), FOREIGN KEY(matchup_id) REFERENCES satellite_matchups (id) ) ;
CREATE INDEX IF NOT EXISTS ix_estimates_photo_id ON estimates (photo_id);
CREATE INDEX IF NOT EXISTS ix_estimates_role ON estimates (role);
CREATE INDEX IF NOT EXISTS ix_estimates_run_id ON estimates (run_id);
CREATE INDEX IF NOT EXISTS ix_estimates_split ON estimates (split);
ALTER TABLE estimates ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON SCHEMA appa FROM PUBLIC, anon, authenticated;
REVOKE ALL ON ALL TABLES IN SCHEMA appa FROM PUBLIC, anon, authenticated;
COMMIT;
